import org.junit.Test;
import org.junit.Assert;
import org.mockito.Mock;
import org.mockito.Mockito;

import java.util.HashSet;
import java.util.Hashtable;
import java.util.Iterator;

public class DBAppTest {

    @Test
    public void createTableTest() throws DBAppException {
        DBApp dbApp = new DBApp();
        Hashtable<String, String> htblColNameType = new Hashtable<>();
        Hashtable<String, String> htblColNameMin = new Hashtable<>();
        Hashtable<String, String> htblColNameMax = new Hashtable<>();
        htblColNameType.put("TestCol", "String");
        htblColNameMin.put("TestCol", "A");
        htblColNameMax.put("TestCol", "Z");
        dbApp.createTable("TestTable", "TestCol", htblColNameType, htblColNameMin, htblColNameMax);
        HashSet<String> tables = dbApp.getMyTables();
        Assert.assertTrue(tables.contains("TestTable"));
    }

    @Test(expected = DBAppException.class)
    public void createTableExceptionTest() throws DBAppException {
        DBApp dbApp = new DBApp();
        Hashtable<String, String> htblColNameType = new Hashtable<>();
        Hashtable<String, String> htblColNameMin = new Hashtable<>();
        Hashtable<String, String> htblColNameMax = new Hashtable<>();
        htblColNameType.put("TestCol", "InvalidType");
        htblColNameMin.put("TestCol", "A");
        htblColNameMax.put("TestCol", "Z");
        dbApp.createTable("TestTable", "TestCol", htblColNameType, htblColNameMin, htblColNameMax);
    }

    @Test
    public void insertIntoTableTest() throws DBAppException {
        DBApp dbApp = new DBApp();
        Hashtable<String, Object> htblColNameValue = new Hashtable<>();
        htblColNameValue.put("TestCol", "TestValue");
        dbApp.insertIntoTable("TestTable", htblColNameValue);

        // Implementation specific: Insert a mock CSV reader to read the inserted rows
        CsvReader mockReader = Mockito.mock(CsvReader.class);
        Mockito.when(mockReader.readNext()).thenReturn(new String[]{"TestValue"});
        dbApp.setReader(mockReader);

        Iterator results = dbApp.selectFromTable(null, null);
        Assert.assertTrue(results.hasNext());
        Assert.assertEquals("TestValue", results.next());
    }

    @Test
    public void updateTableTest() throws DBAppException {
        DBApp dbApp = new DBApp();
        Hashtable<String, Object> htblColNameValue = new Hashtable<>();
        htblColNameValue.put("TestCol", "UpdatedValue");
        dbApp.updateTable("TestTable", "TestValue", htblColNameValue);

        // Implementation specific: Insert a mock CSV reader to read the updated rows
        CsvReader mockReader = Mockito.mock(CsvReader.class);
        Mockito.when(mockReader.readNext()).thenReturn(new String[]{"UpdatedValue"});
        dbApp.setReader(mockReader);

        Iterator results = dbApp.selectFromTable(null, null);
        Assert.assertTrue(results.hasNext());
        Assert.assertEquals("UpdatedValue", results.next());
    }

    @Test
    public void deleteFromTableTest() throws DBAppException {
        DBApp dbApp = new DBApp();
        Hashtable<String, Object> htblColNameValue = new Hashtable<>();
        htblColNameValue.put("TestCol", "UpdatedValue");
        dbApp.deleteFromTable("TestTable", htblColNameValue);

        // Insert a mock CSV reader that reports the row has been deleted
        CsvReader mockReader = Mockito.mock(CsvReader.class);
        Mockito.when(mockReader.readNext()).thenReturn(null);
        dbApp.setReader(mockReader);

        Iterator results = dbApp.selectFromTable(null, null);
        Assert.assertFalse(results.hasNext());
    }
}
